import SettingStore from './Setting/store';
import { ModuleItem, pageDataProps } from './interface';
import { action, computed, observable, toJS, makeObservable } from 'mobx';
import { Message } from '@arco-design/web-react';
import app from '@/store/app';
import { modulePlatform } from '@/types/module';
import { paramListToJSONSchema } from '@/utils/schema';
import { ExpressionContextProps } from '@/types/expression';
import { ConstructorProps, CustomPageStore } from "react-converter-code";
import { getUuid } from '@/utils';
import html2canvas from 'html2canvas';
import business from '@/store/business';
import config from 'mainConfig';

class Store extends CustomPageStore {

  settingId = getUuid();

  isSave = false; // 判断当前模块是否需要保存

  previewId = `prew-${this.uid}`

  // 预览图
  previewImg: string = "";

  setPreviewImg = async () => {
    return ;
    const element = document.getElementById(this.previewId);
    if(element){
      await html2canvas(element, {
      }).then((canvas) => {
        // 获取原始canvas的宽高
        const originalWidth = canvas.width;
        const originalHeight = canvas.height;

        // 计算缩放比例，保持宽高比
        const maxWidth = 800;  // 设定最大宽度为800
        const scale = maxWidth / originalWidth;
        const newWidth = maxWidth;
        const newHeight = originalHeight * scale;

        // 创建新的canvas并设置新宽高
        const resizedCanvas = document.createElement('canvas');
        resizedCanvas.width = newWidth;
        resizedCanvas.height = newHeight;

        // 将原始canvas内容绘制到新的canvas上，调整大小
        const ctx = resizedCanvas.getContext('2d');
        ctx?.drawImage(canvas, 0, 0, newWidth, newHeight);

        // 将新的canvas转换为Base64字符串 (WebP格式)
        const imageData = resizedCanvas.toDataURL('image/webp');
        if (imageData) {
            this.previewImg = imageData;  // 保存Base64图片数据
        }
        // console.log('imageData', imageData)
      });
    }
  }

  @observable formBusiness: any = {};
  @computed get businessBody(){
    if(!this.selectId) return null;
    return this.formBusiness[this.selectId];
  }

  platform = app.platform || modulePlatform.pc;

  getContentData = () => {
    const data = this.getData();
    // @ts-ignore
    // data.previewImg = this.previewImg;
    return data;
  }

  setContentData = (content) => {
    // this.previewImg = content.previewImg;
    this.setData(content);
  }

  validate = async (): Promise<pageDataProps> => {
    if(!this.settingStore.form){
      return this.getContentData();
    }
    return this.settingStore.form.validate().then(() => {
      return this.getContentData();
    })
  }

  // 同props 参数
  openModuleEidt?: (id: string) => void;

  onDoubleClick: any = (item: ModuleItem) => {
    if(item.source === "custom"){
      if(this.openModuleEidt) this.openModuleEidt(item.key);
    }
  }
  
  /**
   * 这里覆盖选中函数
   */
  setSelectId = (id: any) => {
    if(this.selectId == id) return;  // 相同组件
    if(this.settingStore.form){
      this.settingStore.form.validate().then(action(() => {
        this.selectId = this.selectId == id? "" : id ;
      })).catch((error) => {
        console.error(error);
        Message.warning("当前表单验证未通过，请先将当前表单数据完善")
      })
    }else {
      // this.selectId = id;
      this.selectId = this.selectId == id? "" : id ;
    }
  }

  constructor(props: ConstructorProps){
    super(props)

    makeObservable(this);

    this.settingStore = new SettingStore({ pageStore: this });
  }

  settingStore:SettingStore;
  
  @computed get pageContextData(){
    if(this.isPage) return { store: this.contentData };
    return {};
  }


  pageData(){
    // console.log('this.contentData', list, this.contentData, forms)
    return {
        data: {
          config: app.extraInfo.configuration,
          props: this.contentData.props,
          query: this.isComponent? undefined : this.contentData.query,
          data: this.contentData.data,
          methods: this.contentData.methods,
          $refs: this.contentData.$refs,
        },
        dataSchema: {
            type: "object",
            properties: {
                config: app.allVariablesSchema,
                query: this.isComponent? undefined :  paramListToJSONSchema(this.page.query),
                data: this.page.data,
                props: this.isComponent? this.page.props : undefined,
                methods: paramListToJSONSchema(this.page.methods),
            }
        }
    } as ExpressionContextProps
  }
}


export default Store;