import React, { useEffect, useMemo } from 'react';
import { MonacoLessEditor } from '@/components/MonacoEditor';
import { Modal, ModalProps, Form } from '@arco-design/web-react';
import module from "@/store/module";
import { moduleTypes, moduleDisplay } from '@/types/module';
import { JSONSchemaCustom, SchemaForm } from '@/components/schema';
import _ from "lodash";
import { FormGenerateContext, moduleStore } from "react-converter-code";
import { toJS } from 'mobx';
import { getFormats } from '@/environments/formats';


interface SettingProps extends ModalProps {
    id: string;
    onSuccess: (res: any) => void;
}
const Setting = ({ id, onSuccess, ...props }: SettingProps) => {

    const [form] = Form.useForm();
    const values = useMemo(() => {
        const element = moduleStore.elements.get(id);
        const obj = _.pick(element, ['name', 'nickname', 'props', 'category', 'extraInfo', 'display', 'source']);
        obj.extraInfo = toJS(obj.extraInfo);
        return obj;
    }, [])

    const schema = useMemo(() => {
        const element = moduleStore.elements.get(id);
        const schema: JSONSchemaCustom = {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "组件名",
                    "maxLength": 100,
                    "fieldProps": {
                        "placeholder": "请输入组件名",
                    },
                    "show": {
                        "source{}": ["custom", "context"]
                    },
                    "columnProps": {
                        "ellipsis": true,
                        "width": 100,
                    },
                    "formItemProps": {
                        "shouldUpdate": true,
                        "field": "name",
                        rules: [{
                            required: true,
                        }, {
                            match: /[A-Z][A-Za-z0-9]*$/g,
                            message: "当前命名要符合React组件命名规则"
                        }, {
                            validator(value, callback) {
                                if(module.nameMap.has(value) && value !== element.name){
                                    callback("当前组件名称已存在")
                                }
                            },
                        }]
                    },
                },
                "nickname": {
                    "type": "string",
                    "title": "模块名称",
                    "fieldProps": {
                        "placeholder": "请输入模块名称"
                    },
                    "columnProps": {
                        "ellipsis": true,
                        "width": 100,
                    },
                },
                // "props": {
                //     "type": "object",
                //     "title": "参数类型props",
                //     "format": "jsonSchema",
                //     fieldProps:{
                //         showForm: true,
                //         title: "Schema（props）"
                //     },
                // },
                // "extraInfo.initialProps": {
                //     "title": "props初始值",
                //     "formGenerateProps": {
                //         "to": "Modal",
                //         "cols": 24,
                //         "formItemProps": {
                //             "noStyle": true,
                //         }
                //     },
                //     "type": "object",
                //     "format": "json",
                //     "description": "设置组件默认props参数",
                // },
                // "extraInfo.defaultProps": {
                //     "title": "默认参数",
                //     "formGenerateProps": {
                //         "to": "Modal",
                //         "cols": 24,
                //         "formItemProps": {
                //             "noStyle": true,
                //         }
                //     },
                //     "type": "object",
                //     "format": "json",
                //     "description": "设置组件默认props参数",
                // },
                "category": {
                    "type": "string",
                    "title": "模块类别",
                    "maxLength": 50,
                    "show": {
                        "source!{}": ["context"]
                    },
                    "enum": Object.keys(moduleTypes).map((k) => ({ label: moduleTypes[k], value: k })),
                },
                "display": {
                    "type": "string",
                    "title": "展示类型",
                    "maxLength": 20,
                    "show": {
                        "source!{}": ["context"]
                    },
                    "format": "radio",
                    "enum": Object.keys(moduleDisplay).map((k) => ({ label: moduleDisplay[k], value: k })),
                    // "default": "block"
                },
                "extraInfo": {
                    "type": "object",
                    "title": "布局特性",
                    "properties": {
                        "className": {
                            "type": "string",
                            "title": "布局样式",
                            "show": { "source": "custom" },
                        },
                        "portal": {
                            "type": "boolean",
                            "format": "boolean",
                            "title": "布局渲染",
                            "description": "将布局渲染在最外层"
                        },
                        "isOriginal": {
                            "type": "boolean",
                            "format": "boolean",
                            "title": "保持原有特性",
                            "description": "拖动布局下会保持原有特性，(正常布局下只会加载构建的程序）",
                            "show": { "source": "custom" },
                        }
                    }
                },
                "extraInfo.isRef": {
                    "type": "boolean",
                    "format": "boolean",
                    "show": { "formData.source": "custom" },
                    "description": "开启后会使用forwardRef创建组件，ref 会通过props中forwardRef参数传入"
                },
                "extraInfo.refProps": {
                    "type": "object",
                    "show": { "formData.source": "custom" },
                    "format": "jsonSchema",
                    "description": "可以只暴露特定的操作, 定义父组件传入的ref将绑定的schema 类型"
                },
                "extraInfo.refBody": {
                    "type": "string",
                    "show": { "formData.source": "custom" },
                    "format": "function",
                    "fieldProps": {
                        pureFunction: true  
                    },
                    "description": "返回resProps约束对应的类型参数"
                },
            }
        }
        return schema;
    },[])

    return (
        <div onClick={(e) => e.stopPropagation()}>
            <Modal
                title="更新组件"
                style={{ width: 800 }}
                visible
                onOk={async () => {
                    return form.validate().then((res) => {
                        if(onSuccess){
                            return onSuccess(res);
                        }
                    })
                }}
                {...props}
            >
                <FormGenerateContext.Provider value={{ formats: getFormats() }}>
                    <SchemaForm
                        form={form}
                        schema={schema}
                        initialValues={values}
                        generagteProps={{ cols: 12 }}
                        layout="vertical"
                    />
                </FormGenerateContext.Provider>
            </Modal>
        </div>
    )

}

export default Setting;