import React, { useEffect, useMemo, useState } from 'react';
import { Button, Input, InputProps, Message, Modal, Popover, Space, Upload, UploadProps } from '@arco-design/web-react';
import { IconFileImage } from '@arco-design/web-react/icon';
import styles from './index.module.less';
// import ImageList from './ImageList';
import ImageList from './ImageList2';
import Store from './store';
import { Pattern } from '@/types/pattern';
import { useObserver } from 'mobx-react-lite';


interface EditImageProps extends Omit<UploadProps, 'onChange'>  {
    value?: string | string[];
    // 是否开启多选
    multipleChoice?: boolean;
    onChange?: (value: string | string[]) => void;
}
const EditImage = ({
    value,
    multipleChoice,
    onChange,
    ...props
}: EditImageProps) => {

    const [store] = useState(() => new Store());

    return useObserver(() => {

        const { visible, setVisible, listVisible, setListVisible, url, setUrl } = store;
        const isSetting = useMemo(() => {
            if(multipleChoice) return true;
            return store.list.length == 0;
        },[store.list.length,multipleChoice])

        const onChangeList = (list:any[]) => {
            const urls = list.filter((o) => o.status == "done").map((o) => o.url);
            onChange(multipleChoice? urls : urls[0]);
        }

        const values = useMemo(() => {
            if(!value) return [];
            const values = Array.isArray(value)? value : [value];
            return values;
          },[value])

          useEffect(() => {
            if(!values.length) {
              store.setList([]);
            };
            const map = new Map(store.list.filter((o) => o.url).map((o) => [o.url, o]));
            const list = values.filter((url) => !map.has(url));
            for (const url of list) {
                store.addFileUrl(url)
            }
          },[values])

        return (
            <div className={styles.upload}>
                <Upload
                    drag
                    limit={multipleChoice? 9 : 1}
                    multiple
                    imagePreview
                    action='/'
                    listType='picture-card'
                    beforeUpload={() => {
                        Message.warning("当前是测试平台，上传功能已禁用")
                        return false;
                    }}
                    onDrop={(e) => {
                        Message.warning("当前是测试平台，上传功能已禁用")
                    }}
                    onChange={(list) => {
                        // console.log('setList', JSON.parse(JSON.stringify(list[0])))
                        store.setList(list)
                        onChangeList(list);
                    }}
                    accept='image/*'
                    fileList={store.list}
                    {...props}
                >
                    <div className={styles.trigger}
                        onClick={(e) => {
                            Message.warning("当前是测试平台，上传功能已禁用")
                            e.stopPropagation();
                        }}
                        onPaste={(e) => {
                            Message.warning("当前是测试平台，上传功能已禁用")
                            // store.handlePaste(e);
                        }}
                    >
                        点击或拖拽文件到此处上传
                    </div>
                </Upload>
                {isSetting && (
                    <Button.Group style={{ marginTop: 8 }}>
                        <Button
                            onClick={() => {
                                setListVisible(true);
                            }}
                        >本地图库</Button>
                        <Button
                            onClick={() => {
                                setUrl("")
                                setVisible(true)
                            }}
                        >外部图片</Button>
                        <Button type="primary"
                            onClick={() => {
                                Message.warning("当前是测试平台，上传功能已禁用")
                            }}
                        >
                            上传文件
                        </Button>
                    </Button.Group>
                )}
                <Modal
                    visible={visible}
                    title="外部图片"
                    onCancel={() => {
                        setVisible(false)
                    }}
                    unmountOnExit
                    onOk={() => {
                        store.addFileUrl(url)
                        onChangeList(store.list);
                        setVisible(false);
                    }}
                >
                    <Input placeholder="请输入图片链接" value={url}
                        onChange={(value) => {
                            setUrl(value)
                        }} 
                    />
                </Modal>
                <Modal
                    visible={listVisible}
                    style={{ width: 800 }}
                    title="图片列表"
                    onCancel={() => {
                        setListVisible(false)
                    }}
                >
                    <ImageList
                        onImage={(url) => {
                            store.addFileUrl(url)
                            onChangeList(store.list);
                            setListVisible(false)
                        }}
                    />
                </Modal>
            </div>
        )
    })

}

export default EditImage;