import React, { useState, useEffect } from 'react';
import { MonacoJsonProps, MonacoJSONEditor } from '..';
import { Button, Modal } from '@arco-design/web-react';
import { IconCodeBlock } from '@arco-design/web-react/icon';
export type { EditClassProps } from './EditClass';
import EditClassE from './EditClass';
export const EidtClass = EditClassE;
export interface EditStyleProps extends MonacoJsonProps {
    title?: string;
    
}
const EditStyle = ({ title, ...props }: EditStyleProps) => {


    const [visible, setVisible] = useState<boolean>(false);
    const [value, setValue] = useState(props.value);

    useEffect(() => {
        setValue(props.value);
    },[props.value])

    return (
        <div>
            <Button shape='round' type='primary' icon={<IconCodeBlock />}
                onClick={() => {
                    setVisible(true)
                }}
            >
                编辑
            </Button>
            <Modal visible={visible}
                title={title || "Style"}
                focusLock={false}
                style={{ width: 800 }}
                onCancel={() => {
                    setVisible(false)
                }}
                onConfirm={() => {
                    if(props.onChange){
                        props.onChange(value)
                        setVisible(false);
                    }else {
                        setVisible(false);
                    }
                }}
            >
                <MonacoJSONEditor 
                    {...props}
                    type="css"
                />
            </Modal>
        </div>
    )
}

export default EditStyle;
