import { MonacoJSONEditor } from "@/components/MonacoEditor";
import { JSONSchemaCustom, SchemaForm } from "@/components/schema";
import module from "@/store/module";
import { moduleDisplay, modulePlatform, moduleTypes } from "@/types/module";
import { getUuid } from "@/utils";
import ajax from "@/utils/ajax";
import { Form, Modal, ModalProps } from "@arco-design/web-react";
import React, { useMemo } from "react";
import { FormGenerateContext } from "react-converter-code";


interface AddModuleProps extends ModalProps {
    onSuccess: (moduleId?: string) => void;
}



const schema: JSONSchemaCustom = {
    type: "object",
    properties: {
        "name": {
            "type": "string",
            "title": "组件名",
            "maxLength": 100,
            "fieldProps": {
                "placeholder": "请输入组件名",
            },
            "columnProps": {
                "ellipsis": true,
                "width": 100,
            },
            "formItemProps": {
                "shouldUpdate": true,
                "field": "name",
                rules: [{
                    required: true,
                }, {
                    match: /^[A-Z][A-Za-z0-9]*$/g,
                    message: "当前命名要符合React组件命名规则"
                },{
                    validator(value, callback) {
                        if(module.nameMap.has(value)){
                            callback("当前组件名称已存在")
                        }
                    },
                }]
            },
        },
        "nickname": {
            "type": "string",
            "title": "模块名称",
            "fieldProps": {
                "placeholder": "请输入模块名称"
            },
            "columnProps": {
                "ellipsis": true,
                "width": 100,
            },
        },
        "category": {
            "type": "string",
            "title": "模块类别",
            "maxLength": 50,
            "default": "General",
            "enum": Object.keys(moduleTypes).map((k) => ({ label: moduleTypes[k], value: k })),
        },
        "display": {
            "type": "string",
            "title": "展示类型",
            "maxLength": 20,
            "format": "radio",
            "enum": Object.keys(moduleDisplay).map((k) => ({ label: moduleDisplay[k], value: k })),
            "default": "block"
        },
        // "extraInfo.className": {
        //     "type": "string",
        //     "title": "布局样式",
        //     "show": { "source": "custom" },
        // },
        // "extraInfo.isRef": {
        //     "type": "boolean",
        //     "format": "boolean",
        //     "show": { "source": "custom" },
        //     "description": "开启后会使用forwardRef创建组件，ref 会通过props中forwardRef参数传入"
        // },
        // "extraInfo.refProps": {
        //     "type": "object",
        //     "show": { "source": "custom" },
        //     "format": "jsonSchema",
        //     "description": "可以只暴露特定的操作, 定义父组件传入的ref将绑定的schema 类型"
        // },
        // "extraInfo.refBody": {
        //     "type": "string",
        //     "show": { "source": "custom" },
        //     "format": "function",
        //     "fieldProps": {
        //         pureFunction: true  
        //     },
        //     "description": "返回resProps约束对应的类型参数"
        // }
    },
    required: ['source', 'name', 'nickname']
}

const AddModule = (props: AddModuleProps) => {

    const [form] = Form.useForm();


    const createModule = () => {
        return form.validate().then((res) => {
            const id = getUuid();
            return ajax.post('/apijson/post', {
                "Module": {
                    ...res,
                    id: id,
                    moduleId: id,
                    source: "custom",
                    platform: modulePlatform.pc,
                    props: res.props || {},
                    extraInfo: res.extraInfo || {},
                }
            }).then(() => {
                if(props.onSuccess) props.onSuccess(id);
            })
        })
    }

    const context = useMemo<any>(() => {
        return {
            formats: { json: MonacoJSONEditor }
        }
    },[])

    return (
        <Modal 
            title="新增组件"
            style={{ width: 800 }}
            onOk={() => {
                return createModule()
            }}
            {...props}
        >
            <FormGenerateContext.Provider value={context}>
                <SchemaForm 
                    generagteProps={{ cols: 12 }}
                    layout="vertical"
                    schema={schema}
                    form={form}
                />
            </FormGenerateContext.Provider>
        </Modal>
    )

}


export default AddModule;