import ajax from "@/utils/ajax";
import { datasProps } from "./interface";

export default {
  roles: {
    fieldNames: {
      label: 'role_name',
      value: "role_key",
    },
    find: () => {
        return ajax.post('/apijson/get', {
            "Role[]": {
               "Role": {
                 "@column": "role_key,role_name",
                 "role_key!": "admin",
                 "@order": "role_sort+"
               },
            }
        }).then((res) => res.Role)
    }
  }
} as {
    [key in string]: datasProps
};
