import { Tabs, Tooltip, TabsProps } from "@arco-design/web-react";
import { useObserver } from "mobx-react-lite";
import React, { useEffect, useState } from "react";
import Store from '../store';

interface TabHeaderProps extends TabsProps {
    store: Store;
}

const TabHeader = ({ store, ...props }: TabHeaderProps) => {


    return useObserver(() => {

        const [list, setList] = useState([]);

        /**
         * 获取到uri 
         */
        useEffect(() => {
            if(store.uri){
                const path = store.uri.path;
                if(!list.some((o) => o.path == path)){
                    setList([...list, { path: path, name: path.split('/').pop() }])
                }
            }
        },[store.uri])
        
        return (
            <Tabs type="card"
                editable
                showAddButton={false}
                extra={props.extra}
                
                activeTab={store.uri?.path}
                onDeleteTab={(key) => {
                    setList(list.filter((o) => o.path != key));
                }}
                onChange={(key) => {
                    const item = store.contents.find((o) => o.path == key);
                    if(item){
                        store.openFile(item.uri);
                    }
                }}
            >
                {list.map((o) => {
                    return (
                        <Tabs.TabPane
                            key={o.path}
                            title={(
                                <Tooltip content={o.path} >
                                    { o.name }
                                </Tooltip>
                            )}
                            closable
                        >
                        </Tabs.TabPane>
                    )
                })}
            </Tabs>
        )
    })

}

export default TabHeader;