import React, { useState, useCallback, useEffect, ReactNode, useMemo } from 'react';
import '../style.less';
import { delayedFunction } from '@/utils';
import { ResizeBox, ResizeBoxProps, Tabs, Typography, Tooltip } from '@arco-design/web-react';
import Editor from './Editor';
import Contents, { ContentsProps } from './Contents';
import Store from './store';
import TabHeader from './TabHeader';

const { TabPane } = Tabs;

const key = "OJIWENGIOVNSFW";

export interface MonacoCodeProps {
    store?: Store;
    onReady?: () => void;
    extra?: ReactNode;
    right?: ReactNode;
    contentProps?: Partial<ContentsProps>
}

export default function MyComponent(props: MonacoCodeProps) {
    const [store] = useState(() => props.store || new Store());
    const [value, setValue] = useState(localStorage.getItem(key));
    const onTransform: any = useCallback(delayedFunction(setValue, 1000), [])

    useEffect(() => {
        if (props.onReady) props.onReady();
        localStorage.setItem(key, value);
    }, [value])





    const panes = useMemo(() => {
        const list: any[] = [
            {
                size: "200px",
                collapsible: {
                    prev: true,
                },
                content: (
                    <div style={{ height: '100%', overflowY: 'auto', minWidth: 0, width: '100%', flexGrow: 1 }}>
                        <Contents store={store} {...props.contentProps} />
                    </div>
                ),
                hasHidden: false
            },
            {
                min: '10px',
                content: (
                    <div style={{ overflow: 'hidden', height: "100%" }}>
                        <TabHeader extra={props.extra} store={store} />
                        <Editor
                            store={store}
                            ext="tsx"
                            value={value}
                            onChange={onTransform}
                        />
                    </div>
                ),
                hasHidden: false
            }
        ]
        if(props.right){
            list.push({
                min: '50px',
                content: props.right,
                hasHidden: true
            })
        }

        return list;
    },[props.right, props.extra]);


    return (
        <div className="monaco-editor-code">
            <div style={{ height: '100%', width: '100%' }}>
                <ResizeBox.SplitGroup
                    className='resizebox-split-group-demo-horizontal'
                    style={{ height: '100%' }}
                    panes={panes}
                />
            </div>
        </div >
    );
}
