import React, { useEffect, useState } from 'react';
import Store from '../store';
import { Grid, Space, Button } from '@arco-design/web-react';
import ItemView from '../ItemView';
import styles from '../style.module.less';

interface LibraryModulesProps {
    uid: string;
    store: Store;
}

const Index = ({ store, uid }: LibraryModulesProps) => {

    const [modules, setModules] = useState<any[]>([]);

    useEffect(() => {
        store.getLibraryModules(uid).then((list) => {
            setModules(list);
        });
    },[])

    return (
        <div>
            <Space className={styles.lirayHeader}>
                <Button type="primary"
                    onClick={() => {
                        store.syncModule(modules);
                    }}
                >全部下载</Button>
            </Space>
            <Grid.Row gutter={[16,16]} className={styles.allList}>
                {modules.map((o) => {
                    return (
                        <Grid.Col span={6} key={o.id}>
                            <ItemView key={o.id}
                                item={o}
                                // Element={store.m(o.moduleId)}
                            />
                        </Grid.Col>
                    )
                })}
            </Grid.Row>
        </div>
    )
}


export default Index;