import React, { useCallback, useContext, useMemo, useState } from 'react';
import { Button, Empty, Modal, Space, Select, Input, Form, Link, Badge } from "@arco-design/web-react";
import { IconSettings, IconDelete, IconPlusCircle, IconPlus, IconCloseCircle } from "@arco-design/web-react/icon";
import styles from '../index.module.less';
import _ from 'lodash';
import store from '../store';
import { controlConfig } from '@/types/verify';
import FormValue from '../FormValue';

const Option = Select.Option;
const FormItem = Form.Item;

interface FormBodyProps {
    field: string;
    parentField: string;
    remove: () => void;
}
export default ({ field, parentField, remove }: FormBodyProps) => {
    const getField = (key) => field? `${field}.${key}` : key;

    /**
     * 获取操作符
     */
    const getOperatorOptions = useCallback((values) => {
        const list: controlConfig[] = _.get(values, parentField);
        if(!Array.isArray(list)) return store.operatorOptions;
        for (const item of list) {

        }
        return store.operatorOptions;
    },[field])

    return (
        <Space size='small' >
            <FormItem className={styles.mSmall} field={getField('origin')}>
                <Select
                    placeholder='选择数据源'
                    style={{ width: 154 }}
                >
                    {store.originOptions.map((option, index) => (
                        <Option key={index} value={option.value}>
                            {option.label}
                        </Option>
                    ))}
                </Select>
            </FormItem>
            <FormItem noStyle shouldUpdate>
                {(values) => {
                    const options = getOperatorOptions(values);
                    const origin = _.get(values, getField('origin'));
                    const filedOpitons = store.originMap.get(origin) || [];
                    return(
                        <Space>
                            <FormItem className={styles.mSmall} field={getField('field')}>
                                <Select
                                    placeholder='请选择字段'
                                    style={{ width: 154 }}
                                    allowClear
                                    options={filedOpitons}
                                    allowCreate
                                    filterOption={(value, option) => {
                                        if(option.props.children){
                                            return option.props.children.indexOf(value) !== -1;
                                        }
                                        return true;
                                    }}
                                />
                            </FormItem>
                            <FormItem className={styles.mSmall} field={getField('operator')}>
                                <Select
                                    placeholder='请选择运算符'
                                    style={{ width: 154 }}
                                >
                                    {options.map((option, index) => (
                                        <Option key={index} value={option.value}>
                                            {option.label}
                                        </Option>
                                    ))}
                                </Select>
                            </FormItem>
                             <FormValue field={field} values={values} />
                        </Space>
                    )
                }}
            </FormItem>
            <FormItem className={styles.mSmall}>
                <IconDelete onClick={() => { remove() }} className={styles.cursor} />
            </FormItem>
        </Space >
    )
}