    @observable search: string;
    @action
    setSearch = (val) => {
        this.search = val;
    }
    @observable formList: any[] = [];
    @computed get filterFormList (){
        const list = toJS(this.formList);
        if(this.search){
            return list.filter((o) => {
                if(o.field.indexOf(this.search) !== -1) return true;
                if(typeof o.label === 'string' && o.label.indexOf(this.search) !== -1) return true;
                return false;
            })
        }
        return list;
    }

