import { getUuid } from "@/utils";
import { Button, Modal, ModalProps } from "@arco-design/web-react"
import { useEffect, useMemo, useRef, useState } from "react";
import styles from './index.module.less';
import PageStore from '../store';
import { modulePlatform } from "@/types/module";
import { dynamicCreateModule } from "@/environments/hoc";
import MyErrorBoundary from "@/components/custom/MyErrorBoundary";
import { IconMobile } from "@arco-design/web-react/icon";
import MobileView, { MobileStore } from '../mobile/view';
import { useObserver } from "mobx-react-lite";
import { moduleStore } from "react-converter-code";

let timer = null;
interface PreviewProps extends ModalProps {
    pageStore: PageStore;
}
export default ({ pageStore, ...props }: PreviewProps) => {

    const [store] = useState(() => new MobileStore(pageStore));

    return useObserver(() => {

        const { text, setText } = store;
        const [isMobile, setIsMobile] = useState(false);
    
        useEffect(() => {
            if(props.visible){
                pageStore.getRenderText().then((text) => {
                    console.log('text', text);
                    // 动态创建当前text 页面
                    setText(text)
                    
                    if(!pageStore.previewImg){
                        setTimeout(() => pageStore.setPreviewImg(), 100);
                    }

                });
            }
        },[props.visible])

        const PageElement = useMemo(() => {
            if(text){
                return dynamicCreateModule(text);
            }
            return (props) => <span></span>;
        },[text])

        useEffect(() => {
            if(props.visible){
                const timer = setTimeout(() => {
                    // 执行时机再次确认
                    props.visible && pageStore.setPreviewImg()
                }, 5000)
                return () => {
                    clearTimeout(timer);
                }
            }
        }, [PageElement]);

        const modulePropos = useMemo(() => {
            const element = moduleStore.elements.get(pageStore.uid);
            if(!element) return {};
            return element.extraInfo.initialProps;
        },[])
    
    
        
        return (
            <Modal
                title={
                    <div style={{ marginRight: 30, display: "flex", justifyContent: "space-between", }}>
                        <span>预览</span>
                        <Button
                            size="small"
                            type={isMobile? "primary" : "default"}
                            icon={<IconMobile style={{ marginRight: 0 }} />}
                            style={{ marginLeft: 10 }}
                            onClick={() => {
                                setIsMobile(!isMobile)
                            }}
                        />
                    </div>
                }
                className={`${styles.modal} arco-modal-page-html`}
                style={{
                    width: "90%"
                }}
                footer={null}
                maskClosable={false}
                {...props}
            >
                <div id={pageStore.previewId} className={styles.preview}>
                    <MobileView store={store} isMobile={isMobile} />
                </div>
            </Modal>
        )
    })
}