export enum functionHistoryTypes {
    push = "push",
    replace = "replace",
    go = "go",
    goBack = "goBack",
}
/**
 * history 路由配置
 */
export interface functionHistoryConfig {
    // 跳转地址
    path?: string;
    // 操作方法
    type?: functionHistoryTypes,
    // 回退页数
    count?: number;
    // 跳转地址参数
    params?: jsonItem[];
}

