export default `
import { UserInfo } from "../types/user";
import { action, computed, observable } from "mobx";

const tokenKey = "AUTH-TOKEN";

const permissionAll = new Proxy({}, { get(target, prop) { return true }});
/**
 * 当前控制器为管理后台通用
 */
class UserStore {

    // 获取token
    getToken(){
        const token = sessionStorage[tokenKey];
        if(!token) return;
        const time = sessionStorage.getItem(\`\${tokenKey}-express\`);
        if(token && time && Date.now().toString() < time){
            return token;
        }
        return;
    }
    
    // 获取token 过期时间
    /**
     * @title 更新用户token信息
     * @param value token
     * @param expressTime 过期时间，默认6小时
     */
    setToken(value: string, expressTime: number = 6){
        sessionStorage.setItem(tokenKey, value);
        const time = (expressTime * 3600 * 1000) + Date.now();
        sessionStorage.setItem(\`\${tokenKey}-express\`, time.toString());
    }


    @observable userToken = "";
    @action
    setUserToken = (token) => {
        this.userToken = token;
        this.setToken(token)
    }

    @observable info: UserInfo = null;
    // 用户权限点
    @observable permissions: Record<string, boolean> = {};
    @action
    setUser = (data: UserInfo) => {
        this.info = data;
        if(this.roles.includes('admin')){
            this.permissions = permissionAll
        }else {
            this.permissions = data.permissions.reduce((obj, key) => ({ ...obj, [key]: true }), {})
        }
        this.setUserToken(data.accessToken)
    }

    @action assign = (data: Partial<UserInfo>) => {
        this.info = { ...this.info, ...data };
    }

    get roles(){
        if(!this.info) return [];
        return this.info.roles.map((o) => o.role);
    }

  

    get token(){
        return this.userToken;
    }

    @computed get isLogin(){
        return Boolean(this.userToken);
    }




    // 退出登陆
    @action
    logout(){
        sessionStorage.removeItem(tokenKey);
        this.info = null;
        this.userToken = "";
    } 
}

export default new UserStore();
`