import {
  Button,
  Checkbox,
  Drawer,
  Input,
  Modal,
  Space,
  Switch,
  TableColumnProps,
  TableProps,
  Tooltip,
} from '@arco-design/web-react';
import React, { useEffect, useMemo, useState } from 'react';
import Store from '../store';
import { useObserver } from 'mobx-react-lite';
import _ from 'lodash';
import { IconEdit, IconSettings } from '@arco-design/web-react/icon';
import { JSONSchemaItemProps } from '@/types/schema';
import { ExpressionSelect } from '@/components/custom';
import { ProTable } from '@/components/custom';

interface SchemaTableBase extends TableProps {
  readOnly?: boolean;
}
interface SchemaTabelProps extends SchemaTableBase {
  store: Store;
  json?: JSONSchema;
  columnKeys?: string[];
  onChange: () => void;
  isExpression?: boolean;
}

export default function SchemaTabel({
  onChange,
  readOnly,
  columnKeys,
  isExpression,
  ...props
}: SchemaTabelProps) {
  /**
   * 获取当前Table Store 对象
   */
  const [store] = useState(() => {
    if (props.store) return props.store;
    const s = new Store();
    s.setJson(props.json);
    s.setData();
    return s;
  });

  useEffect(() => {
    if (!props.json) return;
    store.setJson(props.json);
    store.setData();
  }, [props.json]);

  const columns: TableColumnProps<JSONSchemaItemProps>[] = useMemo(() => {
    const list = [
      {
        title: '必填',
        dataIndex: '_parentStore', 
        render: (str, record: JSONSchemaItemProps) => {
          const parentPath = record.schemaPath.slice(0, -2)
          const schema: JSONSchema = _.get(store.json, parentPath, {})
          const requireds = schema.required || [];
          return (
            <Switch 
              checked={requireds.includes(record.key)}
              disabled={readOnly}
              onChange={(value) => {
                const list = requireds.filter((k) => k !== record.key)
                if(value){
                  _.set(store.json, [...parentPath, 'required'], [...list, record.key])
                }else {
                  _.set(store.json, [...parentPath, 'required'], list)
                }
                onChange && onChange();
              }}
            />
          )
        }
      },
      {
        title: '标题',
        dataIndex: 'title',
        render: (str: any, record: JSONSchemaItemProps) => {
          return (
            <Input
              placeholder="请输入"
              autoComplete="off"
              defaultValue={record._store.title}
              readOnly={readOnly}
              onChange={(val) => {
                _.set(store.json, [...record.schemaPath, 'title'], val);
                onChange && onChange();
              }}
            />
          );
        }
      },
      {
        title: '字段描述',
        dataIndex: 'description',
        render:(str: any, record: JSONSchemaItemProps) => {
              return (
                <Input
                  placeholder="请输入"
                  autoComplete="off"
                  readOnly={readOnly}
                  defaultValue={record._store.description}
                  onChange={(val) => {
                    _.set(store.json, [...record.schemaPath, 'description'], val);
                    onChange && onChange();
                  }}
                />
              );
            },
      },
      {
        title: '默认值',
        dataIndex: 'default',
        ellipsis: true,
        render: (__, record: JSONSchemaItemProps) => {
          let text = '';
          const str = record._store.default;
          if (str && typeof str !== 'object') text = String(str);
          return (
            <div className="table-default">
              <Tooltip content={text}>
                <div className="table-default-text">{text}</div>
              </Tooltip>
              <div>
                {isExpression && (
                  <ExpressionSelect
                    onChange={(res) => {
                      console.log('ExpressionSelect', store.json)
                      _.set(store.json, [...record.schemaPath, 'default'], res.value);
                      onChange && onChange();
                    }}
                  >
                    <Button
                      type="text"
                      size="small"
                      shape="circle"
                      icon={<IconEdit />}
                    />
                  </ExpressionSelect>
                )}
                {/* <Button size="small" shape='circle' type='primary' icon={<IconSettings />} /> */}
              </div>
            </div>
          );
        },
      },
    ];

    if(columnKeys){
      return list.filter((k) => columnKeys.includes(k.dataIndex));
    }
    return list;
  }, []);

  return useObserver(() => {
    const params = _.omit(props, ['json', 'store']);
    return (
      <React.Fragment>
        <ProTable
          resizable
          scroll={{ y: 300 }}
          columns={[
            {
              title: '路径',
              dataIndex: 'path',
              width: 200,
              ellipsis: true,
              render: (list) => {
                return list.join('.')
              }
            },
            {
              title: 'Type',
              dataIndex: 'type',
            },
            ...columns
          ]}
          pagination={false}
          data={store.data}
          {...params}
        />
      </React.Fragment>
    );
  });
}
