import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Select, SelectProps } from '@arco-design/web-react';
import datas from './datas';
import busData from './busData';
import i18next from 'i18next';
import { datasProps, ParamsProps } from './interface';
import { addGather, getGather } from './gather';
import { schemaToTableColumn } from '@/utils/schema';
import { delayedFunction } from '@/utils';
import { getTranslation, isJsxString, isTranslation } from '@/utils/is';
addGather(datas);
addGather(busData);
const caches = {};
const addCache = (key: string, data: any) => {
    caches[key] = data;
    // 缓存时间设置为10s， 10s后删除掉缓存
    setTimeout(() => {
        delete caches[key];
    },1000 * 10)
}

export interface SelectorProps extends SelectProps {
    // 根据type 置顶数据源
    type?: string;
    // 根据schema 生成列表
    schema?: JSONSchema;
    // 会将参数作为数据源传给查询接口
    params?: Record<string, any>;
    // 帅选options
    filterOption?: (item: any) => boolean;
}

const Selector = ({ type, schema, params, filterOption, ...props}: SelectorProps) => {
    
    const {
        fieldNames, find, onChildNoSelect, isSearch, selectProps, cache
    }: any = useMemo(() => {
        const item: datasProps = getGather()[type];
        if(!item) return {
            selectProps: {}
        };
        const { fieldNames, find, onChildNoSelect, isSearch, cache, ...itemProps } = item;
        return {
            fieldNames: Object.assign({ 
                label: 'name',
                value: 'id',
                disabled: 'disabled'
            }, fieldNames),
            find,
            onChildNoSelect,
            isSearch,
            selectProps: itemProps,
            cache,
        }
    },[type])


    const [options, setOptions] = useState<any[]>([]);

    useEffect(() => {
        if(schema){
            const list = schemaToTableColumn(schema);
            setOptions(list.map((o) => ({
                label: isTranslation(o.title)? i18next.t(getTranslation(o.title)) : o.title,
                value: o.dataIndex
            })))
        }
    },[schema])

    const changeOptiosn = async (list) => {
        if(Array.isArray(list)){
            let options = list;
            // 判断 value 值是否存在
            if(props.value){
                const values = Array.isArray(props.value)? props.value : [props.value];
                const map = new Map(list.map((o) => [o[fieldNames.value], true]))
                const filters = values.filter((key) => map.has(key));
                if(filters.length){
                    // 存在选中的值，在children 中不存在
                    if(onChildNoSelect){
                        await onChildNoSelect(filters).then((item) => {
                            if(item){
                                const items = Array.isArray(item)? item : [item];
                                options = options.concat(items);
                            }
                        })
                    }
                }
            }
            const result = options.map((o) =>{
                const { label, value, disabled } = fieldNames as datasProps['fieldNames'];
                return {
                    ...o,
                    label: typeof label === 'function'? label(o) : o[label],
                    value: o[value],
                    disabled: o[disabled],
                    extra: o,
                }
            })
            setOptions(result);
        }
    }


    /**
     * 获取筛选内容列表
     */
    const onSearch = useCallback((input: string = '') => {
        if(cache && caches[type]) {
            caches[type].then(changeOptiosn);
            return;
        };
        if(find){
            const promise = find({
                input,
                params
            } as ParamsProps)
            if(cache){
                addCache(type, promise)
            }
            promise.then(changeOptiosn);
        }

    },[type, params])

    const delayedSearch = useMemo(() => {
        if(!isSearch) return () => {};
        return delayedFunction(onSearch, 300)
    },[isSearch])
    

    useEffect(() => {
        if(type){
            onSearch()
        }
    },[type, params])

    const resultOptions = useMemo(() => {
        if(filterOption) return options.filter(filterOption);
        return options;
    },[options])

    return (
        <Select
            onSearch={delayedSearch}
            showSearch
            allowClear
            options={resultOptions}
            placeholder="请选择"
            filterOption={(val, option) => {
                const { children, value } = option.props;
                if(children){
                    return children.indexOf(val) !== -1 || (typeof value === "string" && value.indexOf(val) !== -1);
                }
                return true;
            }}
            {...selectProps}
            {...props}
        />
    )
}

export default Selector;