import { Button, ButtonProps, Divider, Message, Modal, Radio, Space, Typography } from "@arco-design/web-react";
import { IconCodeBlock, IconCodeSquare, IconLink } from "@arco-design/web-react/icon";
import CustomPage, { CustomPageProps, CustomPageStore } from "@/components/CustomPage";
import { CustomPageContext } from "@/components/CustomPage/context";
import { useContext, useEffect, useState, useMemo } from "react";
import styles from './index.module.less';
import { pageDataProps } from "@/components/CustomPage/interface";
import _ from 'lodash';
import { Pattern } from "@/types/pattern";

// export interface EditReactNodeProps extends Omit<CustomPageProps, 'store'> {
interface BaseProps {
    value?: pageDataProps['list'] ;
    onChange?: (val: pageDataProps['list']) => void;
}

export type EditFunctionNodeProps = BaseProps & {
    isComponent: boolean;
    widgets?: any;
    value?: any;
    buttonProps?: ButtonProps;
    noParams?: boolean; // 禁止天津 params
    onChange?: (val: any) => void;
}

function EditReactNode({ widgets, buttonProps, noParams, ...props }: EditFunctionNodeProps){

    const [visible, setVisible] = useState<boolean>(false);
    const [radio, setRadio] = useState<"function" | "node">(
        (props.value && typeof props.value === "object")? "node" : "function"
    )
    const data = useContext(CustomPageContext);
    const [store] = useState(() => {
        const pageStore = new CustomPageStore({ 
            // node 节点类型，操作不进行修改
            control: true,
            widgets,
            isFunction: true,
        })
        if(data){
            if('platform' in data){
                pageStore.platform = data.platform;
            }
            pageStore.settingStore.pageSchema = {
                "type": "object",
                "properties": {
                    "countList": {
                        "type": "array",
                        "title": "变量列表",
                        "listType": "Table",
                        "items": {
                            "type": "object",
                            "properties": {
                                countName: {
                                    type: "string",
                                    title: "变量名称",
                                    "pattern": Pattern.namespace,
                                },
                                countValue: {
                                    type: "string",
                                    title: "变量值",
                                    format: "js"
                                },
                                countType: {
                                    type: "string",
                                    title: "变量类型"
                                }
                            }
                        }
                    },
                    "params": {
                        "title": "定义参数信息",
                        "type": "array",
                        show: !noParams,
                        "items": {
                            "type": "string",
                        }
                    }
                }
            };
        }
        pageStore.settingStore.title = "参数设置"
        // console.log('pageStore', pageStore);
        return pageStore;
    })


    useEffect(() => {
        if(!props.value) return;
        if(typeof props.value === "object"){
            store.setData(props.value);
        }
    },[props.value])
    
    return (
        <div>
            <Button 
                type="primary"
                icon={<IconCodeSquare />}
                onClick={() => {
                    setVisible(true);
                }}
                {...buttonProps}
            >FunctionNode</Button>
            <Modal visible={visible}
                alignCenter
                title={"(...args) => ReactNode"}
                focusLock={false}
                className={styles.module}
                style={{ 
                    width: '90vw'
                }}
                onCancel={() => {
                    setVisible(false)
                }}
                onConfirm={() => {
                    if(props.onChange){
                        const { list, page } = store.getData();
                        props.onChange({
                            list,
                            ..._.pick(page, ['countList', 'params']),
                            jsxBody: store.getPageJsxBody()
                        })
                        setVisible(false);
                    }else {
                        setVisible(false);
                    }
                }}
            >
                <CustomPage
                    store={store}
                />
            </Modal>
        </div>
    )
}

export default EditReactNode;