import React, { useEffect, useMemo } from 'react';
import Store from '../store';
import { observer } from 'mobx-react-lite';
import { Button, Dropdown, Form, Grid, Menu, Modal, Message, Pagination, Select, Space, Tag, Tooltip } from '@arco-design/web-react';
import styls from '../style.module.less';
import ItemView from '../ItemView';
import { IconDown, IconMoreVertical } from '@arco-design/web-react/icon';
import app from "@/store/app";
import { toJS } from 'mobx';
import { isPermission } from '@/components/Permission';
import ajax from '@/utils/ajax';

interface AllListProps {
    store: Store;
}

function Index({ store }: AllListProps){

    useEffect(() => {
        store.initLables();
        store.initModules();
    },[])

    const pluginOptions = useMemo(() => {
        return app.plugins.map((o) => {
            return { label: o.id, value: o.id }
        })
    }, [app.plugins])

    const labelOptions = useMemo(() => {
        return store.labels.map((o) => {
            return { label: o.name, value: o.id }
        })
    }, [store.labels])


    const getExtra = useMemo(() => {

        return (item) => {
            const dropList = (
                <Menu>
                  <Menu.Item key='1'
                    onClick={() => {
                        store.syncModule([item]);
                    }}
                  >
                    <Tooltip content="下载此组件到当前租户下">下载</Tooltip>
                  </Menu.Item>
                  {isPermission('system.public.module.delete') && (
                    <Menu.Item key='2'
                        onClick={() => {
                            // 删除线上公开模块
                            Modal.confirm({
                                title: `是否要删除【${item.nickname}】公共组件`,
                                onOk: () => {
                                    return ajax.post('/apijson/delete', {
                                        PublicModule: {
                                            id: item.id
                                        }
                                    }).then(() => {
                                        Message.success("保存成功")
                                        store.initModules();
                                    })
                                }
                            })
                        }}
                    >
                        删除
                    </Menu.Item>
                  )}
                </Menu>
            );
    
            return (
                <Dropdown droplist={dropList} position='bl'>
                    <Button type='text' icon={<IconMoreVertical />} />
                </Dropdown>
    
            )
        }
    },[])

    console.log('labelOptions', toJS(store.labels))
    return (
        <div>
            <div className="flex items-center pb-4">
                {Boolean(app.plugins.length) && (
                    <div className='flex items-center'>
                        <span>插件：</span>
                        <Select options={pluginOptions} placeholder="请选择" />
                    </div>
                )}
                <div className="flex items-center ml-2 w-72">
                    <div className="shrink-0">标签：</div>
                    <Select options={labelOptions} placeholder="请选择" />
                </div>
            </div>
            <div className='p-2'>
                <Grid.Row gutter={[16,16]} className={styls.allList}>
                    {store.modules.map((o) => {
                        return (
                            <Grid.Col span={6} key={o.id}>
                                <ItemView
                                    key={o.id}
                                    item={o}
                                    extra={getExtra(o)}
                                />
                            </Grid.Col>
                        )
                    })}
                </Grid.Row>
            </div>
            <div style={{ display: "flex", justifyContent: "flex-end", margin: "8px 0px" }}>
                <Pagination
                    showTotal
                    total={store.pagin.total}
                    pageSize={20}
                    onPageSizeChange={(size, current) => {
                        store.setPagin({
                            ...store.pagin,
                            page: current,
                        })
                    }}
                />
            </div>
        </div>
    )
}

export default observer(Index);