import React, { useMemo, useState } from 'react';
import { Button, Input, InputProps, Message, Modal, Popover, Image } from '@arco-design/web-react';
import { IconFileImage } from '@arco-design/web-react/icon';
import styles from './index.module.less';
import ImageList from './ImageList';
import file from "@/store/file";
import FileList from './FileList';

interface EditImageProps extends InputProps {

}
const EditImage = (props: EditImageProps) => {

    const [visible, setVisible] = useState(false);

    const imgUrl = useMemo(() => {
        return file.imgMap[props.value];
    },[props.value])

    return (
        <React.Fragment>
            <Input
                className={styles.image}
                {...props}
                addAfter={(
                    <Button type="primary" icon={<IconFileImage />}
                        onClick={() => setVisible(true)}
                    ></Button>
                )}
                placeholder='选择图片'
            />
            {imgUrl? (
                <Image src={imgUrl} width={120} className="mt-2" />
            ): null}
            <Modal title="文件管理" visible={visible}
                style={{ width: 1000 }}
                footer={null}
                className={styles.model}
                onCancel={() => {
                    setVisible(false);
                }}
            >
                <FileList
                    onClick={(o) => {
                        if(props.onChange) {
                            props.onChange(`/static/${o.fileName}`, {});
                            setVisible(false)
                        }
                    }}
                />
            </Modal>
        </React.Fragment>
    )
}

export default EditImage;