import { Input, InputProps } from "@arco-design/web-react"
import { ExpressionSelect } from "../.."

export interface ExpressionBuilderProps extends InputProps {

}
export default (props: ExpressionBuilderProps) => {

    return (
        <Input
            {...props}
            addAfter={(
                <ExpressionSelect 
                    onChange={({ value }) => {
                        if(props.onChange){
                            props.onChange(`${props.value || ''}${value}`, {});
                        }
                    }}
                />
            )}
        />
    )
}