import { observable, action, computed, makeObservable } from 'mobx';

interface constructorProps {
    originStr: string;
}

class FileStore {

    // 当前文件原string 文本
    @observable originStr: string = "";
    @action
    setOriginStr = (val) => {
        this.originStr = val;
    }

    // 当前文件最新文本信息
    @observable dataStr: string = "";
    @action
    setDataStr = (val) => {
        this.dataStr = val;
    }

    @observable loading: boolean = false;
    @action
    setLoading = (bool) => {
        this.loading = bool;
    }

    /**
     * 当前文件是否已经修改
     */
    @computed get isEdit(){
        return this.originStr != this.dataStr;
    }

    constructor({ originStr }: constructorProps){
        makeObservable(this);
        this.originStr = originStr;
        this.dataStr = originStr;
    }
    
}

export default FileStore;