import { useMemo, useState } from 'react';
import { Tree, Checkbox, TreeProps } from '@arco-design/web-react';
import type { TreeDataType } from '@arco-design/web-react/es/Tree/interface';
import classNames from 'classnames';
import './styles.less';
const TreeNode = Tree.Node;

export interface DorpTreeProps extends TreeProps {
    value?: TreeDataType[];
    onChange?: (e: TreeDataType[]) => void;
    // 单层级，不允许多层级拖动
    isSingle?: boolean;
}
function Index({ value, onChange, isSingle, ...props }: DorpTreeProps) {
  const treeData = useMemo(() => {
    if(Array.isArray(value)) return value;
    return [];
  },[value])
  const setTreeData = (list) => {
    if(onChange){
        onChange(list);
    }
  }
  const [allowDrop] = useState(() => {
    if(isSingle){
        return (option) => {
            return option.dropPosition === -1;
        }
    }
  })
  return (
    <Tree
        draggable
        blockNode
        allowDrop={allowDrop}
        onDrop={({ dragNode, dropNode, dropPosition }) => {
            const loop = (data, key, callback) => {
            data.some((item, index, arr) => {
                if (item.key === key) {
                callback(item, index, arr);
                return true;
                }

                if (item.children) {
                return loop(item.children, key, callback);
                }
            });
            };

            const data = [...treeData];
            let dragItem;
            loop(data, dragNode.props._key, (item, index, arr) => {
                arr.splice(index, 1);
                dragItem = item;
                dragItem.className = 'tree-node-dropover';
            });

            if (dropPosition === 0) {
                loop(data, dropNode.props._key, (item, index, arr) => {
                    item.children = item.children || [];
                    item.children.push(dragItem);
                });
            } else {
                loop(data, dropNode.props._key, (item, index, arr) => {
                    arr.splice(dropPosition < 0 ? index : index + 1, 0, dragItem);
                });
            }

            setTreeData([...data]);
            setTimeout(() => {
                dragItem.className = '';
                setTreeData([...data]);
            }, 1000);
        }}
        {...props}
        treeData={treeData}
    ></Tree>
  );
}

export default Index;
