import React, { ReactNode, useEffect, useMemo, useState } from 'react';
import { Button, Spin, Tree, TreeProps } from '@arco-design/web-react';
import * as monaco from 'monaco-editor';
import { IconDown, IconDragArrow, IconDriveFile, IconPlus } from '@arco-design/web-react/icon';
import { useObserver } from 'mobx-react-lite';
import Store from '../store';
import ContentStore from './store';
import { toJS } from 'mobx';
import { convertToTree } from '@/utils';
import styles from './index.module.less';
import classNames from 'classnames';
import FileStore from './fileStore';
const TreeNode = Tree.Node;

interface TreeNameProps {
    title: string | ReactNode;
    fileStore: FileStore;
}
const TreeName = ({ title, fileStore }: TreeNameProps) => {

    return useObserver(() => {
        return (
            <Spin loading={fileStore.loading}>
                <div
                    className={classNames({
                        [styles.isEdit]: fileStore.isEdit,
                        [styles.fileName]: true
                    })}
                >
                    <span className={styles.title}>{title}</span>
                    <span className={styles.dot}></span>
                </div>
            </Spin>
        )
    })
}

export interface ContentsProps extends TreeProps {
    store: Store;
}
const sortList = ['node_modules', 'public', 'locales', 'store', 'context', 'components', 'pages'];
export default ({ store, ...props }: ContentsProps) => {

    const [contentStore] = useState(() => {
        store.nodeModules.map((o) => {
            store.addContents(o.uri);
        })
        return new ContentStore();
    });

    return useObserver(() => {

        const list = useMemo(() => {
            const list = [
                ...store.contents.filter((o) => o.isDir).sort((a,b) => a.fileName.localeCompare(b.fileName)),
                ...store.contents.filter((o) => !o.isDir).sort((a,b) => a.fileName.localeCompare(b.fileName)),
            ].map((o) => {
                return {
                    ...o,
                    icons: {
                        switcherIcon: o.uri? <IconDriveFile /> : <IconDown />,
                    },
                };
            })
            return convertToTree(list, 'path', 'parentPath').sort((a, b) => {
                return sortList.indexOf(a.fileName) - sortList.indexOf(b.fileName);
            });
        },[store.directoryList])


        useEffect(() => {
            if(store.uri){
                const paths = store.uri.path.split('/');
                const length = paths.length;
                for(let i = 0; i < length; i++){
                    // 将这个文件对应的目录打开
                    contentStore.addExpand(paths.slice(0, i+1).join('/'));
                }
                // console.log('store.uri', store);
            }
        },[store.uri])


        // console.log('store.uri', store.uri)

        return (
            <React.Fragment>
                <Tree
                    icons={{
                        // switcherIcon: <IconDown />,
                        // dragIcon: <IconDragArrow />,
                    }}
                    treeData={list}
                    fieldNames={{
                        key: "path",
                        title: 'fileName',
                    }}
                    className={styles.files}
                    selectedKeys={[store.uri?.path]}
                    expandedKeys={contentStore.expandKeys}
                    onExpand={contentStore.setExpands}
                    onSelect={(a,{ selectedNodes }) => {
                        const { dataRef } = selectedNodes[0].props;
                        if(dataRef.uri){
                            // 打开文件
                            store.openFile(dataRef.uri);
                        }else {
                            // 打开目录
                            contentStore.saveExpandStatus(dataRef.path);
                        }
                    }}
                    renderTitle={({ title, dataRef, ...props }) => {
                        const fileStore: any = dataRef.uri && store.fileStores[dataRef.uri.path];
                        if(fileStore){
                            return (
                                <TreeName key={dataRef.key} title={title} fileStore={fileStore} />
                            )
                        }else {
                            return title;
                        }
                    }}
                    //   renderExtra={() => {
                    //     return (
                    //         <span className={styles.dot}>11</span>
                    //     )
                    //   }}
                    showLine
                    //   draggable
                    {...props}
                >
                </Tree>
            </React.Fragment>
        );
    })

}