import React from 'react';
import { Select, Button } from '@arco-design/web-react';
import { IconPlus } from '@arco-design/web-react/icon';
import { ExpressionSelect } from '@/components/custom';

/**
 * 变量多选组件
 */
export default ({ onChange, ...props }: any) => {
    
    return (
        <div
            style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center"
            }}
        >
            <Select mode="multiple" allowCreate onChange={onChange} {...props} />
            <ExpressionSelect
                onChange={({ value }) => {
                    if(Array.isArray(props.value)){
                        onChange([...props.value, value])
                    }else {
                        onChange([value])
                    }
                }}
            >
                <Button type="primary" shape="square"  icon={<IconPlus />}></Button>
            </ExpressionSelect>
        </div>
    )
}